/* Fase 01: interacción visual con datos ficticios guardados solo en este navegador. */
(() => {
  'use strict';
  const D = globalThis.PointDemo;
  const storageKey = 'point-design-prototype-v1';
  let storageAvailable = true;
  let state;
  try { state = JSON.parse(localStorage.getItem(storageKey)); } catch { storageAvailable = false; }
  if (!state || state.version !== 1 || !Array.isArray(state.products) || !Array.isArray(state.sales) || !Array.isArray(state.cart)) state = D.seed();
  let category = 'Todos', search = '', inventoryFilter = 'Todos', productSearch = '', mobileCart = false, paymentMethod = 'cash';
  let menuOpen = false, toastTimer, previousFocus;
  const app = document.querySelector('#app'), modal = document.querySelector('#modal');
  const e = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  const paths = {
    home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    sell: '<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12M13 13h4m-4 4h4"/>',
    box: '<path d="m3 7 9-4 9 4-9 4zM3 7v10l9 4 9-4V7M12 11v10M7 5l9 4"/>',
    layers: '<path d="m3 7 9-4 9 4-9 4zm0 5 9 4 9-4M3 17l9 4 9-4"/>',
    cash: '<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 10h18m-6 5h3M7 2v5"/>',
    settings: '<path d="m9 3 1-1h4l1 3 3 1 3 1v4l-2 2-1 3-1 3h-4l-2-2-3-1-3-1V9l2-2z"/><circle cx="12" cy="11" r="3"/>',
    search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
    plus: '<path d="M12 5v14M5 12h14"/>', minus: '<path d="M5 12h14"/>',
    arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>', chevron: '<path d="m9 5 7 7-7 7"/>',
    down: '<path d="m6 9 6 6 6-6"/>', close: '<path d="m6 6 12 12M18 6 6 18"/>',
    clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    user: '<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    scan: '<path d="M7 3H3v4m14-4h4v4M3 17v4h4m14-4v4h-4M7 8v8m3-8v8m4-8v8m3-8v8"/>',
    check: '<path d="m5 12 4 4L19 6"/>', bag: '<path d="M5 7h14l2 14H3zM8 8V6a4 4 0 0 1 8 0v2"/>',
    card: '<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 10h20M6 15h3"/>',
    wallet: '<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v3m-1 7h5v5h-5a2.5 2.5 0 0 1 0-5"/>',
    transfer: '<path d="M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4"/>',
    print: '<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6zm11-2h1"/>',
    chart: '<path d="M4 3v17h17M8 16v-5m5 5V6m5 10v-7"/>',
    help: '<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3h.01"/>',
    star: '<path d="m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1z"/>',
    trash: '<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
    percent: '<path d="m5 19 14-14"/><circle cx="7" cy="7" r="3"/><circle cx="17" cy="17" r="3"/>',
    edit: '<path d="m15 4 5 5M4 20l4-1L21 6l-5-5L3 14v6z"/>',
    info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
    menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
  };
  const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.box}</svg>`;
  const art = product => {
    const shapes = {
      coffee: '<path d="M43 23h39l6 68H37z" fill="#77523f"/><path d="M45 18h35v10H45z" fill="#402f29"/><rect x="43" y="42" width="39" height="31" rx="2" fill="#f6e9cf"/><path d="M56 62c-6-8 6-15 11-9 5 7-7 16-11 9Z" fill="#77523f"/><path d="m59 62 6-9" stroke="#f6e9cf"/><text x="62" y="87" text-anchor="middle" fill="#e8d5b7" font-size="5" font-weight="700">CAFÉ DE ORIGEN</text>',
      milk: '<path d="m43 30 11-13h25l8 13v64H43z" fill="#e4e9dc"/><path d="M43 30h44v64H43z" fill="#faf9ec"/><path d="m54 17 9 13h24l-8-13z" fill="#c2d7cf"/><path d="M43 52h44v27H43z" fill="#607f7b"/><text x="65" y="63" text-anchor="middle" fill="#fff" font-size="8" font-weight="700">AVENA</text><path d="m58 73 10-5m-8 0 2 6m4-8 2 6" stroke="#f1deb1" stroke-width="2"/><rect x="70" y="21" width="8" height="5" rx="1" fill="#fff"/>',
      bread: '<path d="M22 67c2-32 65-46 83-19 14 24-15 39-41 40-22 1-42-1-42-21" fill="#bd793b"/><path d="M26 63C37 34 85 29 99 48" fill="#dfa65c"/><path d="m48 45-6 22m24-29-6 24m24-24-6 20" stroke="#f2d08c" stroke-width="6" stroke-linecap="round"/>',
      jar: '<rect x="40" y="33" width="48" height="58" rx="12" fill="#ab4b55"/><rect x="38" y="24" width="52" height="15" rx="4" fill="#493b3c"/><rect x="44" y="49" width="40" height="27" rx="2" fill="#fff5df"/><path d="M57 57c-6 7 2 14 7 14s13-7 7-14z" fill="#c55161"/><path d="m59 55 5 3 5-3" fill="none" stroke="#6d8b60" stroke-width="3"/>',
      bottle: '<path d="M56 25h16v14c0 7 12 12 12 25v24a8 8 0 0 1-8 8H52a8 8 0 0 1-8-8V64c0-13 12-18 12-25z" fill="#b1d0ba"/><rect x="54" y="18" width="20" height="12" rx="3" fill="#3c6855"/><path d="M46 59h36v23H46z" fill="#fbfaf2"/><text x="64" y="70" text-anchor="middle" font-size="7" fill="#3c6855" font-weight="700">MINERAL</text><circle cx="63" cy="77" r="3" fill="#78a187"/><path d="M51 49v8" stroke="#e3f1e8" stroke-width="4" stroke-linecap="round"/>',
      cookies: '<rect x="35" y="23" width="58" height="72" rx="5" fill="#cca46e"/><path d="M35 23h58v11H35m0 50h58v11H35" fill="#ab7f4c"/><rect x="41" y="40" width="46" height="39" rx="3" fill="#f7eedc"/><circle cx="64" cy="59" r="15" fill="#ba8447"/><g fill="#725336"><circle cx="59" cy="53" r="2"/><circle cx="69" cy="56" r="2"/><circle cx="61" cy="64" r="2"/><circle cx="71" cy="65" r="2"/></g>',
      chocolate: '<path d="m36 20 57 8-9 70-57-8z" fill="#67515e"/><path d="m36 20 57 8-3 25-57-8z" fill="#3f303e"/><path d="m32 48 57 8-4 32-57-8z" fill="#e7d9d0"/><text x="59" y="66" text-anchor="middle" transform="rotate(8 59 66)" fill="#67515e" font-size="16" font-weight="700">70%</text><text x="59" y="78" text-anchor="middle" transform="rotate(8 59 78)" fill="#67515e" font-size="5">CACAO</text>',
      tea: '<path d="m35 31 48-8 13 11-49 9z" fill="#658776"/><path d="M35 31 47 43v51L35 80z" fill="#4e6d5e"/><path d="m47 43 49-9v51l-49 9z" fill="#e4e9cf"/><path d="M66 72c-6-14 6-21 17-19-1 13-6 20-17 19" fill="#78936b"/><path d="m64 78 15-20" stroke="#536d4f" stroke-width="2"/><text x="70" y="87" text-anchor="middle" fill="#536d4f" font-size="6">TÉ VERDE</text>',
      gift: '<rect x="29" y="42" width="70" height="50" rx="3" fill="#ce947b"/><rect x="25" y="34" width="78" height="15" rx="3" fill="#dfa98f"/><path d="M59 35h11v57H59z" fill="#faf0d8"/><path d="M63 35C39 35 37 13 48 16c8 2 16 19 16 19m0 0c25 0 26-22 15-19-8 2-15 19-15 19" fill="none" stroke="#faf0d8" stroke-width="6"/>',
    };
    return `<svg viewBox="0 0 128 112" class="product-art" aria-hidden="true"><ellipse cx="64" cy="98" rx="37" ry="4" fill="#000" opacity=".07"/>${shapes[product.art] || shapes.gift}</svg>`;
  };
  const nav = [ ['inicio', 'home', 'Inicio'], ['vender', 'sell', 'Punto de venta'], ['productos', 'box', 'Productos'], ['inventario', 'layers', 'Inventario'], ['caja', 'cash', 'Caja'] ];
  const route = () => [...nav.map(item => item[0]), 'configuracion'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'vender';
  const labels = { inicio: 'Tu negocio, de un vistazo', vender: 'Punto de venta', productos: 'Productos y servicios', inventario: 'Inventario', caja: 'Control de caja', configuracion: 'Configuremos tu negocio' };
  function persist() {
    try { localStorage.setItem(storageKey, JSON.stringify(state)); }
    catch { storageAvailable = false; }
  }
  function toast(message) {
    const element = document.querySelector('#toast');
    element.textContent = message; element.classList.add('show'); clearTimeout(toastTimer);
    toastTimer = setTimeout(() => element.classList.remove('show'), 4200);
  }
  function showDialog(html, cls = '') {
    previousFocus = document.activeElement;
    modal.className = cls; modal.innerHTML = html;
    if (!modal.open) modal.showModal();
  }
  const closeButton = `<button type="button" class="icon-button" data-action="close-dialog" aria-label="Cerrar ventana">${icon('close')}</button>`;
  const dialogHeader = (title, subtitle = '') => `<div class="dialog-heading"><div><h2 id="modal-title">${title}</h2>${subtitle ? `<p>${subtitle}</p>` : ''}</div>${closeButton}</div>`;
  const empty = (title, message, symbol = 'box') => `<div class="empty-state">${icon(symbol)}<h3>${title}</h3><p>${message}</p></div>`;
  const status = product => product.stock === null ? '<span class="badge neutral">Servicio</span>' : product.stock === 0 ? '<span class="badge danger">Agotado</span>' : product.stock <= product.min ? '<span class="badge warning">Stock bajo</span>' : '<span class="badge success">Disponible</span>';
  const field = (label, name, value, attributes = '') => `<label class="field">${label}<input name="${name}" value="${e(value)}" ${attributes}></label>`;
  const date = value => new Intl.DateTimeFormat('es-MX', { timeZone: 'America/Mexico_City', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(value));

  function render() {
    const current = route();
    document.title = `POINT · ${labels[current]}`;
    app.innerHTML = `<div class="workspace ${menuOpen ? 'menu-open' : ''}">
      <aside class="sidebar" aria-label="Navegación principal">
        <a class="brand" href="#inicio" aria-label="POINT, ir al inicio">point<span>●</span><small>TODO EN UNO</small></a>
        <div class="business-card"><span class="business-avatar">${e(state.business.name.slice(0, 1))}</span><div><strong>${e(state.business.name)}</strong><small>${e(state.business.branch)}</small></div></div>
        <span class="nav-label">TU OPERACIÓN</span>
        <nav>${nav.map(([id, symbol, text]) => `<a href="#${id}" aria-label="${text}" class="nav-item ${current === id ? 'active' : ''}" ${current === id ? 'aria-current="page"' : ''}>${icon(symbol)}<span>${text}</span>${current === id ? '<i></i>' : ''}</a>`).join('')}</nav>
        <div class="sidebar-bottom"><div class="phase-card"><span class="phase-dot"></span> Espacio de prueba<p>Explora tu próximo<br>punto de venta.</p><button data-action="guide">Ver recorrido ${icon('arrow')}</button></div><a href="#configuracion" aria-label="Configuración" class="nav-item ${current === 'configuracion' ? 'active' : ''}">${icon('settings')}<span>Configuración</span></a><button class="nav-item" data-action="help" aria-label="Ayuda y atajos">${icon('help')}<span>Ayuda y atajos</span></button><div class="profile"><span class="avatar">A</span><div><strong>${e(state.business.owner)}</strong><small>Propietaria · Ejemplo</small></div></div></div>
      </aside>
      <button class="menu-scrim" data-action="menu" aria-label="Cerrar menú"></button>
      <div class="main-shell">
        <header class="topbar"><div class="topbar-start"><button class="icon-button menu-toggle" data-action="menu" aria-label="Abrir menú" aria-expanded="${menuOpen}">${icon('menu')}</button><span class="breadcrumb">Mi negocio ${icon('chevron')} <strong>${e(nav.find(item => item[0] === current)?.[2] || 'Configuración')}</strong></span></div><div class="topbar-right"><span class="location">${e(state.business.branch)}</span><a href="#caja" class="cash-status ${state.cash.open ? '' : 'closed'}"><span></span>Caja ${state.cash.open ? 'abierta' : 'cerrada'}</a><button class="icon-button" data-action="help" aria-label="Ayuda">${icon('help')}</button></div></header>
        <div class="demo-strip">${icon('info')} <span><strong>Prototipo de diseño</strong><span class="demo-detail"> · Datos de ejemplo. No procesa cobros reales.</span></span><button data-action="guide">Guía de revisión ${icon('arrow')}</button></div>
        <main id="content" tabindex="-1" class="main-content ${current === 'vender' ? 'pos-content' : ''}">${({ inicio: dashboard, vender: pos, productos: catalog, inventario: inventory, caja: cashView, configuracion: onboarding })[current]()}</main>
        <nav class="mobile-nav" aria-label="Accesos rápidos">${nav.map(([id, symbol, text]) => `<a href="#${id}" ${current === id ? 'aria-current="page"' : ''}>${icon(symbol)}<span>${id === 'vender' ? 'Vender' : text}</span></a>`).join('')}</nav>
      </div>
    </div>`;
    if (!storageAvailable) document.querySelector('.demo-detail').textContent = ' · Cambios temporales: almacenamiento local no disponible.';
  }
  function pageHeading(title, subtitle, actions = '') {
    return `<div class="page-heading"><div><div class="eyebrow">POINT / ${e(state.business.name)}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;
  }
  function productGrid() {
    const term = search.toLocaleLowerCase('es-MX').trim();
    const filtered = state.products.filter(product => (category === 'Todos' || (category === 'Favoritos' ? ['p1', 'p2', 'p3'].includes(product.id) : product.category === category)) && `${product.name} ${product.sku} ${product.barcode}`.toLocaleLowerCase('es-MX').includes(term));
    return filtered.length ? filtered.map(product => `<button class="product-card ${product.stock === 0 ? 'sold-out' : ''}" data-action="add" data-id="${e(product.id)}" ${product.stock === 0 ? 'disabled' : ''} aria-label="Agregar ${e(product.name)}, ${D.money(product.price)}${product.stock === 0 ? ', agotado' : ''}"><div class="product-visual ${e(product.color)}">${art(product)}${product.stock === 0 ? '<span class="stock-tag">Agotado</span>' : product.stock !== null && product.stock <= product.min ? '<span class="stock-tag low">Últimas piezas</span>' : ''}<span class="add-circle">${icon('plus')}</span></div><div class="product-info"><strong>${e(product.name)}</strong><small>${e(product.detail)}</small><div><b>${D.money(product.price)}</b><span>${product.stock === null ? 'Servicio' : `${product.stock} disponibles`}</span></div></div></button>`).join('') : empty('No encontramos productos', 'Prueba con otro nombre, SKU o código de barras.', 'search');
  }
  function pos() {
    const summary = D.totals(state);
    return `${pageHeading('Todo listo para vender', 'Una buena venta empieza con una operación sencilla.', `<button class="button secondary" data-action="holds">${icon('clock')}En espera <span class="count">${state.held.length}</span></button>`)}
      ${!state.cash.open ? `<div class="notice warning-notice">${icon('cash')} La caja está cerrada. Puedes armar tu carrito y abrir caja para cobrar. <a href="#caja">Ir a caja ${icon('arrow')}</a></div>` : ''}
      <div class="pos-layout"><section class="catalog-panel" aria-label="Buscar y agregar productos"><div class="search-row"><label class="search-field">${icon('search')}<input id="product-search" type="search" placeholder="Buscar producto, SKU o escanear código…" value="${e(search)}" aria-label="Buscar producto, SKU o código"><kbd>F2</kbd></label><button class="button square secondary" data-action="scan" aria-label="Usar lector de código de barras">${icon('scan')}</button></div><div class="category-tabs" role="group" aria-label="Filtrar por categoría">${['Todos', 'Favoritos', ...new Set(state.products.map(p => p.category))].map(cat => `<button data-action="category" data-value="${e(cat)}" class="chip ${category === cat ? 'selected' : ''}" aria-pressed="${category === cat}">${cat === 'Favoritos' ? icon('star') : ''}${e(cat)}</button>`).join('')}</div><div class="catalog-caption"><h2>Elige un producto</h2><span>Precios en MXN · Impuestos incluidos</span></div><div class="product-grid" id="product-grid">${productGrid()}</div><div class="keyboard-hint">${icon('scan')} Escanea un código para agregarlo al carrito <span><kbd>F2</kbd> Buscar <kbd>F4</kbd> Cobrar</span></div></section>
      <aside class="cart-panel ${mobileCart ? 'cart-visible' : ''}" aria-label="Carrito de venta"><div class="cart-heading"><div><h2>Venta actual <span class="count">${summary.count}</span></h2><p>Ticket de prueba · Caja 01</p></div><button class="icon-button" data-action="clear" aria-label="Vaciar carrito" ${state.cart.length ? '' : 'disabled'}>${icon('trash')}</button><button class="icon-button mobile-only" data-action="toggle-cart" aria-label="Cerrar carrito">${icon('close')}</button></div><button class="customer-select" data-action="customer">${icon('user')}<span>${e(state.customer || 'Público en general')}<small>${state.customer ? 'Cliente de ejemplo' : 'Agregar cliente a la venta'}</small></span>${icon('chevron')}</button><div class="cart-items">${summary.lines.length ? summary.lines.map(line => `<div class="cart-item"><div class="mini-art ${e(line.product.color)}">${art(line.product)}</div><div class="cart-item-detail"><strong>${e(line.product.name)}</strong><small>${D.money(line.product.price)} / ${e(line.product.unit)}</small><div class="quantity"><button data-action="quantity" data-id="${e(line.id)}" data-delta="-1" aria-label="Quitar una unidad de ${e(line.product.name)}">${icon('minus')}</button><span>${line.qty}</span><button data-action="quantity" data-id="${e(line.id)}" data-delta="1" aria-label="Sumar una unidad de ${e(line.product.name)}">${icon('plus')}</button></div></div><div class="cart-item-price"><strong>${D.money(line.gross)}</strong><button class="icon-button" data-action="remove" data-id="${e(line.id)}" aria-label="Quitar ${e(line.product.name)}">${icon('close')}</button></div></div>`).join('') : empty('Tu próxima venta empieza aquí', 'Selecciona un producto o escanea su código para agregarlo.', 'bag')}</div><div class="cart-footer"><div class="cart-tools"><button data-action="discount" ${state.cart.length ? '' : 'disabled'}>${icon('percent')}Descuento${state.discount ? ` · ${state.discount}%` : ''}</button><button data-action="note">${icon('edit')}${state.notes ? 'Editar nota' : 'Agregar nota'}</button></div><div class="summary-row"><span>Productos</span><span>${D.money(summary.gross)}</span></div>${summary.discount ? `<div class="summary-row discount-row"><span>Descuento (${state.discount}%)</span><span>−${D.money(summary.discount)}</span></div>` : ''}<div class="summary-row"><span>Impuestos incluidos ${icon('info')}</span><span>${D.money(summary.tax)}</span></div><div class="total-row"><span>Total</span><strong>${D.money(summary.total)}</strong></div><button class="button primary checkout-button" data-action="checkout" ${summary.count && state.cash.open ? '' : 'disabled'}><span>${icon('wallet')} Cobrar ${summary.total ? D.money(summary.total) : ''}</span>${icon('arrow')}</button><button class="hold-button" data-action="hold" ${state.cart.length ? '' : 'disabled'}>${icon('clock')} Guardar en espera</button><small class="cart-disclaimer">Venta simulada. No se mueve dinero real.</small></div></aside></div><button class="mobile-cart-button" data-action="toggle-cart">${icon('bag')} Ver venta (${summary.count}) <strong>${D.money(summary.total)}</strong>${icon('arrow')}</button>`;
  }
  function dashboard() {
    const todayTotal = state.sales.reduce((sum, sale) => sum + sale.total, 0), low = state.products.filter(p => p.stock !== null && p.stock <= p.min);
    return `${pageHeading(`Tu negocio, de un vistazo`, `Hola, ${e(state.business.owner)}. Este es el resumen de tu espacio de prueba.`, `<a class="button primary" href="#vender">${icon('plus')} Nueva venta</a>`)}<div class="overview-banner"><div><span class="badge success">UN BUEN DÍA PARA CRECER</span><h2>Menos tareas.<br>Más tiempo para tu negocio.</h2><p>Vende, cobra y lleva el control desde un solo lugar.</p><a href="#vender">Ir al punto de venta ${icon('arrow')}</a></div><div class="overview-illustration">${art({ art: 'coffee' })}${art({ art: 'milk' })}${art({ art: 'bread' })}<span class="floating-check">${icon('check')} Todo en orden</span></div></div><div class="stat-grid"><article class="stat-card"><span>Ventas de prueba ${icon('chart')}</span><strong>${D.money(todayTotal)}</strong><small>Solo operaciones de este prototipo</small></article><article class="stat-card"><span>Tickets de prueba ${icon('bag')}</span><strong>${state.sales.length.toString().padStart(2, '0')}</strong><small>Consulta el detalle más abajo</small></article><article class="stat-card"><span>Ticket promedio ${icon('wallet')}</span><strong>${D.money(state.sales.length ? Math.round(todayTotal / state.sales.length) : 0)}</strong><small>Promedio de tus ventas simuladas</small></article><article class="stat-card"><span>Productos por revisar ${icon('layers')}</span><strong>${low.length.toString().padStart(2, '0')}</strong><small>Agotados o con pocas existencias</small></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Actividad reciente</h2><p>Las ventas que realices aquí aparecerán en esta lista.</p></div><span class="badge neutral">Datos de prueba</span></div>${salesTable()}</section><section class="panel"><div class="panel-heading"><div><h2>Atención al inventario</h2><p>Un vistazo a tus próximos pendientes.</p></div></div>${low.map(p => `<div class="stock-alert"><div class="mini-art ${e(p.color)}">${art(p)}</div><div><strong>${e(p.name)}</strong><small>${p.stock} ${p.unit === 'pieza' ? 'piezas' : 'unidades'} disponibles</small></div>${status(p)}</div>`).join('')}<a class="text-link panel-link" href="#inventario">Revisar inventario ${icon('arrow')}</a></section></div>`;
  }
  function salesTable() {
    return state.sales.length ? `<div class="table-scroll"><table><thead><tr><th>Ticket</th><th>Cliente</th><th>Pago</th><th>Total</th><th><span class="sr-only">Ver ticket</span></th></tr></thead><tbody>${state.sales.slice(0, 8).map(sale => `<tr><td><strong>${e(sale.id)}</strong><small>${date(sale.createdAt)}</small></td><td>${e(sale.customer)}</td><td><span class="badge neutral">${{ cash: 'Efectivo', card: 'Terminal externa', transfer: 'Transferencia' }[sale.method]}</span></td><td class="amount">${D.money(sale.total)}</td><td><button class="icon-button" data-action="ticket" data-id="${e(sale.id)}" aria-label="Ver ticket ${e(sale.id)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('Aún no hay ventas de prueba', 'Realiza tu primera venta desde el punto de venta.');
  }
  function catalog() {
    return `${pageHeading('Tu catálogo, en orden', 'Todo lo que vendes, con su precio y disponibilidad.', `<button class="button primary" data-action="product-new">${icon('plus')} Nuevo producto</button>`)}<section class="panel"><div class="table-toolbar"><label class="search-field">${icon('search')}<input type="search" id="catalog-search" placeholder="Buscar por nombre, SKU o código…" aria-label="Buscar en el catálogo" value="${e(productSearch)}"></label><span class="muted">${state.products.length} productos y servicios</span></div><div class="table-scroll" id="catalog-table">${catalogRows()}</div></section><div class="notice">${icon('info')} El catálogo es de ejemplo. Los cambios se guardan únicamente en este navegador.</div>`;
  }
  function catalogRows() {
    const filtered = state.products.filter(p => `${p.name} ${p.sku} ${p.barcode}`.toLowerCase().includes(productSearch.toLowerCase()));
    return filtered.length ? `<table><thead><tr><th>Producto</th><th>SKU</th><th>Categoría</th><th>Precio</th><th>Estado</th><th>Editar</th></tr></thead><tbody>${filtered.map(p => `<tr><td><div class="product-cell"><div class="mini-art ${e(p.color)}">${art(p)}</div><div><strong>${e(p.name)}</strong><small>${e(p.detail)}</small></div></div></td><td class="sku">${e(p.sku)}</td><td>${e(p.category)}</td><td class="amount">${D.money(p.price)}</td><td>${status(p)}</td><td><button class="icon-button" data-action="product-edit" data-id="${e(p.id)}" aria-label="Editar ${e(p.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table>` : empty('No encontramos productos', 'Prueba con otro nombre o código.', 'search');
  }
  function inventory() {
    const physical = state.products.filter(p => p.stock !== null);
    const shown = physical.filter(p => inventoryFilter === 'Todos' || (inventoryFilter === 'Stock bajo' ? p.stock > 0 && p.stock <= p.min : p.stock === 0));
    return `${pageHeading('Cada pieza, bajo control', 'Consulta existencias y explora cómo se registrará cada movimiento.', `<span class="warehouse-label">${icon('layers')} Almacén principal</span>`)}<div class="inventory-stats"><div><small>Unidades disponibles</small><strong>${physical.reduce((sum, p) => sum + p.stock, 0)}</strong></div><div><small>Productos con stock bajo</small><strong>${physical.filter(p => p.stock > 0 && p.stock <= p.min).length}</strong></div><div><small>Productos agotados</small><strong>${physical.filter(p => !p.stock).length}</strong></div><div><small>Movimientos de prueba</small><strong>${state.movements.length}</strong></div></div><section class="panel"><div class="table-toolbar"><div class="category-tabs compact">${['Todos', 'Stock bajo', 'Agotados'].map(filter => `<button class="chip ${inventoryFilter === filter ? 'selected' : ''}" data-action="inventory-filter" data-value="${filter}" aria-pressed="${inventoryFilter === filter}">${filter}</button>`).join('')}</div><span class="muted">${shown.length} productos</span></div>${shown.length ? `<div class="table-scroll"><table><thead><tr><th>Producto</th><th>Existencia</th><th>Mínimo</th><th>Estado</th><th>Movimiento</th></tr></thead><tbody>${shown.map(p => `<tr><td><div class="product-cell"><div class="mini-art ${e(p.color)}">${art(p)}</div><div><strong>${e(p.name)}</strong><small>${e(p.sku)}</small></div></div></td><td><strong>${p.stock}</strong> <span class="muted">pzas.</span></td><td>${p.min}</td><td>${status(p)}</td><td><button class="button small secondary" data-action="stock" data-id="${e(p.id)}">${icon('transfer')} Ajustar</button><button class="icon-button" data-action="kardex" data-id="${e(p.id)}" aria-label="Ver movimientos de ${e(p.name)}">${icon('clock')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('Todo en orden por aquí', 'No hay productos con este estado.', 'check')}</section><div class="notice">${icon('info')} Cada ajuste de ejemplo pide un motivo y conserva un movimiento. Los servicios no controlan inventario.</div>`;
  }
  function cashView() {
    const expected = D.cashExpected(state), closed = state.cash.closed;
    return `${pageHeading('Tu caja, con cuentas claras', 'Apertura, movimientos y cierre en un solo lugar.', `<span class="badge ${state.cash.open ? 'success' : 'neutral'}">${state.cash.open ? 'Turno de prueba abierto' : 'Sin turno abierto'}</span>`)}<div class="cash-layout"><section class="panel cash-overview"><div class="panel-heading"><div><span class="eyebrow">SUCURSAL CENTRO</span><h2>Caja 01 · Mostrador</h2><p>${e(state.business.owner)} · Operador de ejemplo</p></div><span class="cash-symbol">${icon('cash')}</span></div><div class="cash-amount"><small>${state.cash.open ? 'Efectivo esperado en caja' : 'Abre un turno para comenzar'}</small><strong>${state.cash.open ? D.money(expected) : '—'}</strong><span>Pesos mexicanos · MXN</span></div><div class="cash-breakdown"><div><span>Fondo inicial</span><strong>${D.money(state.cash.fund)}</strong></div><div><span>Ventas en efectivo de este turno</span><strong>${D.money(state.sales.filter(s => s.session === state.cash.session && s.method === 'cash').reduce((sum, s) => sum + s.total, 0))}</strong></div><div><span>Entradas y retiros</span><strong>${D.money(state.cash.entries.reduce((sum, m) => sum + m.amount, 0))}</strong></div></div><div class="cash-actions">${state.cash.open ? `<button class="button secondary" data-action="cash-movement">${icon('transfer')} Registrar movimiento</button><button class="button primary" data-action="cash-close">Hacer corte ${icon('arrow')}</button>` : `<button class="button primary" data-action="cash-open">${icon('plus')} Abrir caja de prueba</button>`}</div></section><section class="panel"><div class="panel-heading"><div><h2>Antes de cerrar</h2><p>Un cierre transparente, siempre.</p></div></div><ol class="steps-list"><li><span>1</span><div><strong>Cuenta tu efectivo</strong><p>Incluye el fondo inicial y los movimientos de tu turno.</p></div></li><li><span>2</span><div><strong>Compara los importes</strong><p>POINT muestra el esperado, lo contado y la diferencia.</p></div></li><li><span>3</span><div><strong>Confirma el corte</strong><p>Una diferencia siempre queda visible para su revisión.</p></div></li></ol>${closed ? `<div class="closing-result"><span class="badge ${closed.difference ? 'warning' : 'success'}">Último corte de prueba</span><p>Esperado <strong>${D.money(closed.expected)}</strong></p><p>Contado <strong>${D.money(closed.counted)}</strong></p><p>Diferencia <strong>${D.money(closed.difference)}</strong></p>${closed.reason ? `<small>${e(closed.reason)}</small>` : ''}</div>` : '<div class="cash-tip">Los pagos en terminal o transferencia se registran por separado del efectivo físico.</div>'}</section></div><section class="panel"><div class="panel-heading"><div><h2>Movimientos del turno</h2><p>Entradas y retiros de esta demostración.</p></div></div>${state.cash.entries.length ? `<div class="table-scroll"><table><thead><tr><th>Movimiento</th><th>Motivo</th><th>Importe</th></tr></thead><tbody>${state.cash.entries.map(m => `<tr><td>${m.amount > 0 ? 'Entrada' : 'Retiro'}</td><td>${e(m.reason)}</td><td class="amount">${D.money(m.amount)}</td></tr>`).join('')}</tbody></table></div>` : empty('Sin entradas ni retiros', 'Prueba un movimiento para revisar cómo cambia el efectivo esperado.', 'cash')}</section>`;
  }
  function onboarding() {
    const step = state.onboardingStep || 1;
    const names = ['Tu negocio', 'Sucursal', 'Preferencias', 'Todo listo'];
    return `${pageHeading('Hagámoslo tuyo', 'Explora la configuración inicial con información ficticia.')}<div class="onboarding-layout"><aside class="setup-sidebar"><h2>Unos pasos.<br>Todo conectado.</h2><p>Tu negocio merece herramientas que le hagan la vida más fácil.</p><ol>${names.map((name, index) => `<li class="${index + 1 === step ? 'current' : index + 1 < step ? 'done' : ''}"><span>${index + 1 < step ? icon('check') : index + 1}</span><div><strong>${name}</strong><small>${['Nombre e identidad', 'Dónde sucede todo', 'Cómo vas a operar', 'Tu primera venta'][index]}</small></div></li>`).join('')}</ol><div class="setup-note">${icon('info')} Este recorrido no crea una cuenta real ni acepta términos o contratos.</div></aside><section class="panel setup-form"><span class="eyebrow">PASO ${step} DE 4</span><h2>${['Cuéntanos de tu negocio', 'Tu primera sucursal', 'A tu manera', 'Tu negocio está listo para explorar'][step - 1]}</h2><p>${['Este nombre aparecerá en tu espacio y en los tickets de ejemplo.', 'Un lugar para organizar ventas, inventario y caja.', 'Estas preferencias muestran cómo será el inicio de POINT.', 'Ya puedes recorrer tu punto de venta y hacer una venta simulada.'][step - 1]}</p><form data-form="onboarding" data-step="${step}">${step === 1 ? `${field('Nombre comercial de ejemplo', 'businessName', state.business.name, 'required maxlength="45" autocomplete="off"')}${field('Tu nombre de ejemplo', 'owner', state.business.owner, 'required maxlength="30" autocomplete="off"')}<label class="field">Tipo de negocio<select name="businessType"><option>Tienda de productos y servicios</option><option>Comercio de productos</option><option>Negocio de servicios</option></select></label>` : step === 2 ? `${field('Nombre de la sucursal de ejemplo', 'branch', state.business.branch, 'required maxlength="45"')}${field('Leyenda para el ticket de prueba', 'ticket', state.business.ticket, 'maxlength="100"')}<div class="notice">${icon('layers')} Se muestra un almacén principal y una caja de mostrador.</div>` : step === 3 ? `<div class="preference-list"><div>${icon('check')} Productos y servicios <span>Incluido</span></div><div>${icon('layers')} Control de inventario <span>Activo</span></div><div>${icon('scan')} Lector de códigos <span>Como teclado</span></div><div>${icon('cash')} Ventas sin stock <span>Bloqueadas</span></div></div><div class="notice">${icon('info')} México · MXN · Español · America/Mexico_City. La personalización completa llegará con la implementación.</div>` : `<div class="setup-complete">${icon('check')}<h3>${e(state.business.name)}</h3><p>${e(state.business.branch)}</p><div class="badge success">Listo para una venta de prueba</div></div>`}<div class="setup-buttons">${step > 1 ? '<button type="button" class="button secondary" data-action="setup-back">Volver</button>' : '<span></span>'}<button class="button primary" type="submit">${step < 4 ? 'Continuar' : 'Ir a vender'}${icon('arrow')}</button></div></form></section></div>`;
  }

  function checkout() {
    const t = D.totals(state);
    showDialog(`${dialogHeader('Un paso más. Venta lista.', 'Simulación de cobro · No se procesa ningún pago real.')}<div class="payment-layout"><div class="payment-summary"><span>TOTAL A COBRAR</span><strong>${D.money(t.total)}</strong><small>${t.count} ${t.count === 1 ? 'artículo' : 'artículos'} · Impuestos incluidos</small><div>${t.lines.map(line => `<p><span>${line.qty} × ${e(line.product.name)}</span><b>${D.money(line.total)}</b></p>`).join('')}</div>${t.discount ? `<p>Descuento aplicado: ${D.money(t.discount)}</p>` : ''}<div class="payment-demo">${icon('info')} Todos los importes son de ejemplo.</div></div><form data-form="payment"><h3>¿Cómo te pagan?</h3><div class="payment-methods">${[['cash', 'wallet', 'Efectivo'], ['card', 'card', 'Terminal externa'], ['transfer', 'transfer', 'Transferencia']].map(([id, symbol, text]) => `<button type="button" class="payment-method ${id === paymentMethod ? 'selected' : ''}" data-action="payment-method" data-value="${id}" aria-pressed="${id === paymentMethod}">${icon(symbol)}${text}${id === paymentMethod ? icon('check') : ''}</button>`).join('')}</div>${paymentMethod === 'cash' ? `${field('Efectivo recibido', 'received', (t.total / 100).toFixed(2), 'inputmode="decimal" required autocomplete="off"')}<div class="cash-presets">${[20000, 50000, 100000].filter(value => value >= t.total).map(value => `<button type="button" data-action="preset" data-value="${value}">${D.money(value)}</button>`).join('')}</div><div class="change-display"><span>Tu cambio</span><strong id="change-value">${D.money(0)}</strong></div>` : `<div class="notice">${icon('info')} En la versión funcional registrarás un pago realizado fuera de POINT. Aquí solo revisamos el recorrido.</div>`}<p id="form-error" class="form-error" role="alert"></p><button type="submit" class="button primary full-width" id="confirm-payment">${icon('check')} Confirmar venta de prueba</button><p class="form-footnote">Esta acción solo modifica los datos ficticios del navegador.</p></form></div>`, 'wide-dialog');
  }
  function showTicket(sale, success = false) {
    showDialog(`${dialogHeader(success ? '¡Así de fácil se vende!' : 'Ticket de prueba', success ? 'La venta simulada quedó registrada en este navegador.' : 'Reimpresión de la misma venta simulada.')}<div id="print-area" class="receipt"><div class="receipt-brand">point<span>●</span></div><h3>${e(sale.business.name)}</h3><p>${e(sale.business.branch)} · Caja 01</p><div class="receipt-demo">EJEMPLO · SIN VALIDEZ FISCAL</div><div class="receipt-meta"><span>${e(sale.id)}</span><span>${date(sale.createdAt)}</span></div>${sale.items.map(item => `<div class="receipt-line"><span>${item.qty} × ${e(item.name)}</span><strong>${D.money(item.total)}</strong></div>`).join('')}<div class="receipt-divider"></div><div class="receipt-line"><span>Subtotal sin impuestos</span><span>${D.money(sale.subtotal)}</span></div><div class="receipt-line"><span>Impuestos de ejemplo</span><span>${D.money(sale.tax)}</span></div>${sale.discount ? `<small>Descuento incluido: ${D.money(sale.discount)}</small>` : ''}<div class="receipt-total"><span>Total</span><strong>${D.money(sale.total)}</strong></div><div class="receipt-line"><span>${{ cash: 'Efectivo recibido', card: 'Terminal externa', transfer: 'Transferencia' }[sale.method]}</span><span>${D.money(sale.received)}</span></div>${sale.method === 'cash' ? `<div class="receipt-line"><span>Cambio</span><strong>${D.money(sale.change)}</strong></div>` : ''}<p>Cliente: ${e(sale.customer)}</p>${sale.notes ? `<p>Nota: ${e(sale.notes)}</p>` : ''}<p class="receipt-thanks">${e(sale.business.ticket)}</p></div><div class="dialog-actions"><button class="button secondary" data-action="print">${icon('print')} Imprimir ejemplo</button><button class="button primary" data-action="close-dialog">${success ? 'Nueva venta' : 'Listo'}${icon('arrow')}</button></div>`, 'receipt-dialog');
  }
  function productForm(id) {
    const p = state.products.find(product => product.id === id);
    showDialog(`${dialogHeader(p ? 'Editar producto de ejemplo' : 'Agrega algo nuevo', 'Explora los campos esenciales de tu catálogo.')}<form data-form="product" data-id="${e(id || '')}"><div class="form-grid">${field('Nombre', 'name', p?.name || '', 'required maxlength="60"')}${field('SKU', 'sku', p?.sku || '', 'required maxlength="24" pattern="[A-Za-z0-9_-]+"')}<label class="field">Tipo<select name="type"><option value="product" ${p?.stock !== null ? 'selected' : ''}>Producto físico</option><option value="service" ${p?.stock === null ? 'selected' : ''}>Servicio</option></select></label><label class="field">Categoría<select name="category">${['Despensa', 'Bebidas', 'Panadería', 'Servicios', 'Otros'].map(cat => `<option ${p?.category === cat ? 'selected' : ''}>${cat}</option>`).join('')}</select></label>${field('Precio final de ejemplo (MXN)', 'price', p ? (p.price / 100).toFixed(2) : '', 'required inputmode="decimal"')}${field('Código de barras', 'barcode', p?.barcode || '', 'maxlength="30" inputmode="numeric"')}<label class="field span-2">Descripción corta<input name="detail" value="${e(p?.detail || '')}" maxlength="65"></label><label class="field">Impuesto de ejemplo incluido<select name="tax"><option value="0" ${!p?.tax ? 'selected' : ''}>Sin importe de impuesto · Demo</option><option value="0.16" ${p?.tax ? 'selected' : ''}>Tasa de muestra 16% · Demo</option></select></label><div class="form-note">Los productos nuevos comienzan sin existencias. Agrega una entrada de prueba desde Inventario.</div></div><p id="form-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Cancelar</button><button type="submit" class="button primary">${icon('check')} Guardar ejemplo</button></div></form>`, 'form-dialog');
  }
  function simpleForm(title, subtitle, kind, content, button = 'Guardar') {
    showDialog(`${dialogHeader(title, subtitle)}<form data-form="${kind}">${content}<p id="form-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">${button}${icon('check')}</button></div></form>`);
  }
  const formError = message => { const element = modal.querySelector('#form-error'); if (element) element.textContent = message; };
  function updateReceived() {
    const value = D.cents(modal.querySelector('[name="received"]').value), total = D.totals(state).total;
    modal.querySelector('#change-value').textContent = value === null ? 'Revisa el importe' : value < total ? `Faltan ${D.money(total - value)}` : D.money(value - total);
    modal.querySelector('#confirm-payment').disabled = value === null || value < total;
  }
  function guide() {
    showDialog(`${dialogHeader('Conoce tu próximo punto de venta', 'Fase 01 · Diseño y navegación para revisar juntos.')}<ol class="steps-list guide-list"><li><span>1</span><div><strong>Arma una venta</strong><p>Agrega café y pan; cambia cantidades, cliente o descuento.</p></div></li><li><span>2</span><div><strong>Prueba el cobro</strong><p>Elige efectivo, escribe lo recibido y revisa el cambio y el ticket.</p></div></li><li><span>3</span><div><strong>Recorre el negocio</strong><p>Consulta productos, inventario, movimientos y el resumen de caja.</p></div></li><li><span>4</span><div><strong>Hazlo tuyo</strong><p>Prueba la configuración inicial y revisa el uso desde móvil.</p></div></li></ol><div class="notice">${icon('info')} Prototipo local con datos ficticios. Sin cuentas, permisos reales, facturas ni cobros bancarios.</div><div class="dialog-actions"><button class="button secondary" data-action="reset-confirm">Reiniciar ejemplos</button><button class="button primary" data-action="close-dialog">Empezar a explorar ${icon('arrow')}</button></div>`);
  }
  document.addEventListener('click', event => {
    if (event.target.closest('.skip-link')) { event.preventDefault(); document.querySelector('#content').focus(); return; }
    const button = event.target.closest('[data-action]');
    if (!button || button.disabled) return;
    const { action, id, value } = button.dataset;
    if (action === 'close-dialog') { modal.close(); return; }
    if (action === 'menu') { menuOpen = !menuOpen; render(); return; }
    if (action === 'guide') { guide(); return; }
    if (action === 'help') { showDialog(`${dialogHeader('Todo a la mano', 'Atajos para vender con menos pasos.')}<div class="shortcut-list"><p><span>Buscar un producto</span><kbd>F2</kbd></p><p><span>Ir al cobro</span><kbd>F4</kbd></p><p><span>Agregar código exacto</span><kbd>Enter</kbd></p><p><span>Cerrar ventana</span><kbd>Esc</kbd></p></div><p class="muted">Un lector USB que funciona como teclado puede escribir un código en la búsqueda y enviar Enter.</p><div class="dialog-actions"><button class="button primary" data-action="guide">Ver recorrido ${icon('arrow')}</button></div>`); return; }
    if (action === 'category') { category = value; render(); return; }
    if (action === 'inventory-filter') { inventoryFilter = value; render(); return; }
    if (action === 'toggle-cart') { mobileCart = !mobileCart; render(); return; }
    if (action === 'add' || action === 'quantity') { const error = D.addItem(state, id, action === 'quantity' ? Number(button.dataset.delta) : 1); if (error) toast(error); else { persist(); render(); } return; }
    if (action === 'remove') { state.cart = state.cart.filter(item => item.id !== id); persist(); render(); return; }
    if (action === 'clear') { simpleForm('¿Vaciar esta venta de prueba?', 'Los productos del carrito se quitarán. No se ha cobrado nada.', 'clear', '<p>Puedes guardar la venta en espera si deseas retomarla después.</p>', 'Vaciar carrito'); return; }
    if (action === 'scan') { document.querySelector('#product-search').focus(); toast('Escanea un código o escribe, por ejemplo, 7501000000011 y pulsa Enter.'); return; }
    if (action === 'discount') { simpleForm('Descuento para esta venta', 'Ajuste visual de prueba. La autorización real se implementará después.', 'discount', field('Porcentaje de ejemplo', 'discount', state.discount, 'type="number" min="0" max="50" step="1" required')); return; }
    if (action === 'customer') { simpleForm('Cliente de la venta', 'Usa un nombre ficticio o deja el campo vacío para público en general.', 'customer', field('Nombre de ejemplo', 'customer', state.customer, 'maxlength="50" autocomplete="off"')); return; }
    if (action === 'note') { simpleForm('Una nota para recordar', 'Se mostrará en el ticket de ejemplo.', 'note', `<label class="field">Nota de ejemplo<textarea name="notes" maxlength="200" rows="3">${e(state.notes)}</textarea></label>`); return; }
    if (action === 'hold') { if (!state.cart.length) return; state.held.push({ id: `h-${Date.now()}`, cart: structuredClone(state.cart), discount: state.discount, customer: state.customer, notes: state.notes }); state.cart = []; state.discount = 0; state.customer = ''; state.notes = ''; persist(); render(); toast('Venta de prueba guardada en espera.'); return; }
    if (action === 'holds') { showDialog(`${dialogHeader('Ventas en espera', 'Retoma una venta cuando lo necesites.')} ${state.held.length ? state.held.map((held, index) => `<div class="held-row"><div><strong>Venta en espera ${index + 1}</strong><small>${e(held.customer || 'Público en general')} · ${held.cart.reduce((sum, item) => sum + item.qty, 0)} artículos</small></div><button class="button secondary small" data-action="restore" data-id="${held.id}">Recuperar ${icon('arrow')}</button></div>`).join('') : empty('No hay ventas en espera', 'Arma un carrito y pulsa Guardar en espera.', 'clock')}`); return; }
    if (action === 'restore') { if (state.cart.length) { toast('Guarda o vacía la venta actual antes de recuperar otra.'); return; } const index = state.held.findIndex(h => h.id === id); if (index < 0) return; const held = state.held.splice(index, 1)[0]; Object.assign(state, { cart: held.cart, discount: held.discount, customer: held.customer, notes: held.notes }); persist(); modal.close(); render(); return; }
    if (action === 'checkout') { if (!state.cash.open || !state.cart.length) return; paymentMethod = 'cash'; checkout(); return; }
    if (action === 'payment-method') { paymentMethod = value; checkout(); return; }
    if (action === 'preset') { modal.querySelector('[name="received"]').value = (Number(value) / 100).toFixed(2); updateReceived(); return; }
    if (action === 'ticket') { const sale = state.sales.find(s => s.id === id); if (sale) showTicket(sale); return; }
    if (action === 'print') { window.print(); return; }
    if (action === 'product-new' || action === 'product-edit') { productForm(id); return; }
    if (action === 'stock') { const p = state.products.find(p => p.id === id); simpleForm(`Movimiento · ${e(p.name)}`, `Existencia de ejemplo: ${p.stock} piezas`, 'stock', `<input type="hidden" name="id" value="${e(id)}"><label class="field">Tipo de movimiento<select name="direction"><option value="1">Entrada de prueba</option><option value="-1">Salida de prueba</option></select></label>${field('Cantidad de piezas', 'quantity', '1', 'type="number" min="1" max="9999" step="1" required')}${field('Motivo del ajuste', 'reason', '', 'required minlength="3" maxlength="100" placeholder="Por ejemplo: Conteo de prueba"')}`); return; }
    if (action === 'kardex') { const p = state.products.find(p => p.id === id); const movements = state.movements.filter(m => m.productId === id); showDialog(`${dialogHeader(`Movimientos · ${e(p.name)}`, 'Historial local generado durante la demostración.')}${movements.length ? movements.map(m => `<div class="movement-row"><div><strong>${e(m.label)}</strong><small>${date(m.createdAt)} · Existencia después: ${m.after}</small></div><span class="badge ${m.quantity > 0 ? 'success' : 'neutral'}">${m.quantity > 0 ? '+' : ''}${m.quantity}</span></div>`).join('') : empty('Sin movimientos de prueba', 'Registra un ajuste o vende este producto para ver su historial.', 'clock')}`); return; }
    if (action === 'cash-open') { simpleForm('Abre tu caja de prueba', 'Indica con cuánto efectivo inicia este turno de ejemplo.', 'cash-open', field('Fondo inicial (MXN)', 'fund', '500.00', 'inputmode="decimal" required'), 'Abrir caja'); return; }
    if (action === 'cash-movement') { simpleForm('Registra un movimiento', 'El importe afecta únicamente al efectivo de este turno de prueba.', 'cash-movement', `<label class="field">Movimiento<select name="direction"><option value="1">Entrada de efectivo</option><option value="-1">Retiro de efectivo</option></select></label>${field('Importe (MXN)', 'amount', '', 'inputmode="decimal" required')}${field('Motivo', 'reason', '', 'required minlength="3" maxlength="100"')}`); return; }
    if (action === 'cash-close') { simpleForm('Un cierre con cuentas claras', 'Cuenta el efectivo y revisa la diferencia antes de confirmar.', 'cash-close', `<div class="change-display"><span>Efectivo esperado</span><strong>${D.money(D.cashExpected(state))}</strong></div>${field('Efectivo contado (MXN)', 'counted', '', 'inputmode="decimal" required')}<div class="summary-row"><span>Diferencia</span><strong id="closing-difference">—</strong></div>${field('Observación del corte', 'reason', '', 'maxlength="150" placeholder="Obligatoria si hay una diferencia"')}`, 'Cerrar caja de prueba'); return; }
    if (action === 'setup-back') { state.onboardingStep = Math.max(1, state.onboardingStep - 1); persist(); render(); return; }
    if (action === 'reset-confirm') { simpleForm('¿Reiniciar los ejemplos?', 'Se restaurará el catálogo y se borrarán solo las ventas y cambios de esta demostración.', 'reset', '<p>Esta acción afecta únicamente al prototipo local de POINT.</p>', 'Reiniciar demostración'); return; }
  });
  document.addEventListener('input', event => {
    const element = event.target;
    if (element.id === 'product-search') { search = element.value; document.querySelector('#product-grid').innerHTML = productGrid(); }
    if (element.id === 'catalog-search') { productSearch = element.value; document.querySelector('#catalog-table').innerHTML = catalogRows(); }
    if (element.name === 'received') updateReceived();
    if (element.name === 'counted') { const counted = D.cents(element.value); modal.querySelector('#closing-difference').textContent = counted === null ? 'Revisa el importe' : D.money(counted - D.cashExpected(state)); }
  });
  document.addEventListener('submit', event => {
    const form = event.target.closest('form[data-form]'); if (!form) return;
    event.preventDefault(); const data = new FormData(form), kind = form.dataset.form;
    const text = name => String(data.get(name) || '').trim();
    if (kind === 'payment') { const result = D.completeSale(state, paymentMethod, D.cents(text('received'))); if (result.error) { formError(result.error); return; } persist(); mobileCart = false; render(); showTicket(result.sale, true); return; }
    if (kind === 'clear') { state.cart = []; state.discount = 0; }
    if (kind === 'customer') state.customer = text('customer');
    if (kind === 'note') state.notes = text('notes');
    if (kind === 'discount') { const amount = Number(text('discount')); if (!Number.isInteger(amount) || amount < 0 || amount > 50) { formError('Usa un porcentaje entero entre 0 y 50.'); return; } state.discount = amount; }
    if (kind === 'product') {
      const price = D.cents(text('price')), id = form.dataset.id, old = state.products.find(p => p.id === id);
      const sku = text('sku').toUpperCase(), barcode = text('barcode');
      if (!text('name') || !sku || price === null || price <= 0) { formError('Agrega nombre, SKU y un precio mayor a cero con hasta dos decimales.'); return; }
      if (state.products.some(p => p.id !== id && (p.sku.toUpperCase() === sku || (barcode && p.barcode === barcode)))) { formError('Ese SKU o código de barras ya existe en el catálogo de ejemplo.'); return; }
      if (old && (state.cart.some(item => item.id === id) || state.held.some(h => h.cart.some(item => item.id === id)))) { formError('Termina o vacía las ventas que contienen este producto antes de editarlo.'); return; }
      if (old && old.stock > 0 && text('type') === 'service') { formError('Un producto con existencias no puede convertirse en servicio.'); return; }
      const product = { ...(old || {}), id: id || `p-${Date.now()}`, name: text('name'), detail: text('detail') || (text('type') === 'service' ? 'Servicio' : 'Producto'), sku, barcode, category: text('category'), price, stock: text('type') === 'service' ? null : old?.stock ?? 0, min: old?.min || 5, unit: text('type') === 'service' ? 'servicio' : 'pieza', tax: Number(text('tax')), art: old?.art || 'gift', color: old?.color || 'mint' };
      if (old) state.products[state.products.indexOf(old)] = product; else state.products.push(product);
    }
    if (kind === 'stock') {
      const p = state.products.find(p => p.id === text('id')), qty = Number(text('quantity')) * Number(text('direction'));
      if (!p || !Number.isInteger(qty) || !qty || Math.abs(qty) > 9999 || text('reason').length < 3) { formError('Indica una cantidad válida y un motivo de al menos tres caracteres.'); return; }
      if (p.stock + qty < 0) { formError('La salida no puede dejar existencias negativas.'); return; }
      p.stock += qty; state.movements.unshift({ id: `m-${Date.now()}`, productId: p.id, label: text('reason'), quantity: qty, after: p.stock, createdAt: new Date().toISOString() });
    }
    if (kind === 'cash-open') { const fund = D.cents(text('fund')); if (fund === null) { formError('Escribe un fondo válido con hasta dos decimales.'); return; } state.cash = { ...state.cash, open: true, fund, entries: [], session: `session-${Date.now()}` }; }
    if (kind === 'cash-movement') {
      const amount = D.cents(text('amount'));
      if (!state.cash.open || amount === null || amount <= 0 || text('reason').length < 3) { formError('Indica un importe mayor a cero y un motivo. La caja debe estar abierta.'); return; }
      const signed = amount * Number(text('direction'));
      if (D.cashExpected(state) + signed < 0) { formError('El retiro no puede superar el efectivo esperado.'); return; }
      state.cash.entries.unshift({ amount: signed, reason: text('reason') });
    }
    if (kind === 'cash-close') {
      const counted = D.cents(text('counted')), expected = D.cashExpected(state);
      if (counted === null) { formError('Escribe el efectivo contado con hasta dos decimales.'); return; }
      if (counted !== expected && text('reason').length < 3) { formError('Agrega una observación para explicar la diferencia de caja.'); return; }
      state.cash.closed = { counted, expected, difference: counted - expected, reason: text('reason') }; state.cash.open = false;
    }
    if (kind === 'onboarding') {
      const step = Number(form.dataset.step);
      if (step === 1) { if (!text('businessName') || !text('owner')) return; state.business.name = text('businessName'); state.business.owner = text('owner'); state.business.type = text('businessType'); }
      if (step === 2) { if (!text('branch')) return; state.business.branch = text('branch'); state.business.ticket = text('ticket'); }
      state.onboardingStep = step < 4 ? step + 1 : 1; persist();
      if (step === 4) location.hash = 'vender'; else render(); return;
    }
    if (kind === 'reset') { state = D.seed(); category = 'Todos'; search = ''; productSearch = ''; inventoryFilter = 'Todos'; }
    persist(); modal.close(); render(); toast(kind === 'reset' ? 'Ejemplos restaurados. Puedes empezar de nuevo.' : 'Cambio guardado en la demostración.');
  });
  document.addEventListener('keydown', event => {
    if (modal.open) return;
    if (event.key === 'F2') { event.preventDefault(); if (route() !== 'vender') location.hash = 'vender'; requestAnimationFrame(() => document.querySelector('#product-search')?.focus()); }
    if (event.key === 'F4') { event.preventDefault(); if (state.cart.length && state.cash.open) { paymentMethod = 'cash'; checkout(); } else toast('Agrega productos y abre caja para cobrar.'); }
    if (event.key === 'Enter' && event.target.id === 'product-search') {
      event.preventDefault(); const p = state.products.find(p => p.barcode === search.trim() || p.sku.toLowerCase() === search.trim().toLowerCase());
      if (p) { const error = D.addItem(state, p.id); if (error) toast(error); else { search = ''; persist(); render(); document.querySelector('#product-search')?.focus(); } } else toast('Escribe un SKU o código exacto para agregar con Enter.');
    }
  });
  modal.addEventListener('click', event => { if (event.target === modal) { const rect = modal.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) modal.close(); } });
  modal.addEventListener('close', () => { if (previousFocus?.isConnected) previousFocus.focus(); else document.querySelector('#content')?.focus({ preventScroll: true }); });
  window.addEventListener('hashchange', () => { menuOpen = false; mobileCart = false; if (modal.open) modal.close(); render(); document.querySelector('#content').focus({ preventScroll: true }); window.scrollTo(0, 0); });
  render();
})();
